def transform(grid):
    h, w = len(grid), len(grid[0])
    # Turn each diagonal track into a repeating horizontal stripe sequence.
    tracks = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                tracks.setdefault(v, []).append((r, c))

    # Track order is determined by where each diagonal enters the grid;
    # a two-cell-wide track contributes twice.
    items = []
    for color, cells in tracks.items():
        start = min(cells, key=lambda p: (p[0], p[1]))
        width = max(c for r, c in cells if r == start[0]) - start[1] + 1
        items.append((start[0], start[1], color, width))
    items.sort()
    seq = []
    for _, _, color, width in items:
        seq.extend([color] * width)

    if not seq:
        return [row[:] for row in grid]
    return [[seq[r % len(seq)]] * w for r in range(h)]
