    # The input's diagonal strokes define a repeating sequence across
    # diagonals. Collect their colors by diagonal offset (column - row).
    offsets = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                offsets.setdefault(c - r, set()).add(v)

    # Each stroke occupies one or more neighboring diagonals. Build the
    # sequence from the distinct diagonal offsets, keeping adjacent repeats.
    entries = []
    for d in sorted(offsets):
        entries.append(min(offsets[d]))
    if not entries:
        return [row[:] for row in grid]

    # Repeat the diagonal pattern over the whole grid. The output is a
    # diagonal-periodic tiling, with successive rows shifted by one.
    period = len(entries)
    return [[entries[(c - r) % period] for c in range(w)] for r in range(h)]
