def transform(grid):
    h, w = len(grid), len(grid[0])
    tracks = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                tracks.setdefault(v, []).append((r, c))

    # The diagonals mark color positions in a repeating diagonal pattern.
    # Determine its period from the spacing of the marked diagonals.
    offsets = {}
    for color, cells in tracks.items():
        for r, c in cells:
            offsets.setdefault(c - r, color)

    # Track width gives the motif length; use the smallest period that
    # places every marked diagonal consistently.
    ds = sorted(offsets)
    period = max(1, max(ds) - min(ds) + 1)
    for p in range(1, period + 1):
        if all(offsets[a] == offsets[b] for a in ds for b in ds
               if (a - b) % p == 0):
            period = p
            break

    motif = [0] * period
    base = min(ds)
    for d, color in offsets.items():
        motif[(d - base) % period] = color

    # Extend the marked motif diagonally across the canvas.
    return [[motif[(c - r - base) % period] for c in range(w)]
            for r in range(h)]
